sysdrills/06-concurrency-and-throughput/.solution:
export function drainSeconds(backlog, processPerSec, arrivePerSec) {
  return backlog / (processPerSec - arrivePerSec);
}

export function backlogAfter(backlog, processPerSec, arrivePerSec, seconds) {
  return Math.max(0, backlog + (arrivePerSec - processPerSec) * seconds);
}

