sysdrills/06-concurrency-and-throughput/.solution:
export function batchMs(fixedMs, perItemMs, items) {
  return fixedMs + perItemMs * items;
}

export function itemsPerSec(fixedMs, perItemMs, items) {
  return (items * 1000) / batchMs(fixedMs, perItemMs, items);
}

